export function describeProbe(result){if(!result)return 'No diagnostic response';const status=Number(result.status)||0;if(status===401||status===403)return `Server access denied (HTTP ${status}); credentials, expired token, connection limit or required User-Agent/Referer. A 403 alone cannot identify which.`;if(status===404)return 'Source link missing or expired (HTTP 404).';if(status===410)return 'Source link expired or removed (HTTP 410).';if(status===429)return 'Provider rate/connection limit (HTTP 429).';if(status>=500)return `Provider server returned HTTP ${status}.`;if(status>=200&&status<400)return `Server reachable (HTTP ${status}); codec/playback still unverified${result.contentType?' · '+result.contentType:''}.`;return `Source could not be reached${result.message?' · '+result.message:''}.`;}
