export function createLibraryStore({indexedDB,storage,timeout=5000}={}){
 const KEY='tl-library-fallback-v1';let opening;
 function recovery(){try{const raw=storage?.getItem(KEY);return raw?JSON.parse(raw):null;}catch(e){if(e.name==='SecurityError')return null;throw Error('Saved library recovery cannot be read.');}}
 function open(){if(opening)return opening;opening=new Promise((resolve,reject)=>{let req,done=false;const timer=setTimeout(()=>fail(Error('Database open timeout')),timeout);function fail(e){if(done)return;done=true;clearTimeout(timer);reject(e);}try{if(!indexedDB)throw Error('IndexedDB unavailable');req=indexedDB.open('TiviLoom',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('library'))req.result.createObjectStore('library');};req.onerror=()=>fail(req.error);req.onblocked=()=>fail(Error('Database blocked'));req.onsuccess=()=>{if(done){req.result.close();return;}done=true;clearTimeout(timer);req.result.onversionchange=()=>{req.result.close();opening=null;};resolve(req.result);};}catch(e){fail(e);}});return opening;}
 async function transaction(action,value){const db=await open();return new Promise((resolve,reject)=>{let tx,result;const timer=setTimeout(()=>{try{tx?.abort();}catch{}reject(Error('Database transaction timeout'));},timeout);try{tx=db.transaction('library',action==='get'?'readonly':'readwrite');const store=tx.objectStore('library'),req=action==='get'?store.get('active'):action==='delete'?store.delete('active'):store.put(value,'active');req.onsuccess=()=>result=req.result;tx.oncomplete=()=>{clearTimeout(timer);resolve(result);};tx.onerror=tx.onabort=()=>{clearTimeout(timer);reject(tx.error||req.error||Error('Database transaction failed'));};}catch(e){clearTimeout(timer);reject(e);}});}
 return {async get(){const value=recovery();return value||transaction('get');},async put(value){try{await transaction('put',value);storage?.removeItem(KEY);return {backend:'indexedDB'};}catch(primary){try{if(!storage)throw Error('localStorage unavailable');const json=JSON.stringify(value);storage.setItem(KEY,json);if(storage.getItem(KEY)!==json)throw Error('Write verification failed');return {backend:'localStorage'};}catch(secondary){throw Error('Playlist was not saved. IndexedDB: '+primary.name+'; local storage: '+secondary.name+'. Storage may be blocked or full.');}}},async delete(){await transaction('delete');storage?.removeItem(KEY);}};
}
