export function archiveURL(channel,programme,now=Date.now()){if(!channel||!programme||!channel.catchupSource||!programme.start||!programme.end||programme.end>now)return null;const duration=Math.max(1,Math.round((programme.end-programme.start)/1000));const begin=Math.floor(programme.start/1000);if(channel.catchupDays>0&&now-programme.start>channel.catchupDays*86400000)return null;let url=channel.catchupSource.replace(/\{(utc|start|timestamp)\}/gi,String(begin)).replace(/\{(duration|length)\}/gi,String(duration)).replace(/\{(offset)\}/gi,String(Math.round((now-programme.start)/1000)));try{const result=new URL(url,channel.url);return ['http:','https:'].includes(result.protocol)?result.href:null;}catch{return null;}}
