 async function parsedSource(p){if(!p.sourceURL)throw Error('Enter the playlist URL in Edit playlist first.');const text=await ctx.api('source',{url:p.sourceURL,userAgent:p.userAgent});const parsed=await ctx.parsePlaylist(text,platform.sourceBase(p.sourceURL));const cr=p.channels.find(c=>c.xtream?.server)?.xtream;if(cr){const additions=[];for(const [action,convert] of [['get_vod_streams',xtreamMovie],['get_series',xtreamSeries]]){try{const rows=JSON.parse(await ctx.api('source',{url:xtreamApi(cr.server,cr.username,cr.password,action)}));if(!Array.isArray(rows))throw Error('Invalid catalog');for(const row of rows){const item=convert(row,cr);if(item)additions.push(item);}}catch{additions.push(...p.channels.filter(c=>action==='get_vod_streams'?c.xtream?.vodId:c.xtream?.seriesId));toast('Provider catalog unavailable; saved catalog retained.');}}const urls=new Set(additions.map(c=>c.url).filter(Boolean));parsed.channels=parsed.channels.filter(c=>!urls.has(c.url));parsed.channels.push(...additions);}let epg={programs:p.programs||[],names:p.epgNames||{}};const epgURL=p.epgURL||parsed.epg;if(epgURL){try{epg=await ctx.api('epg',{url:epgURL,userAgent:p.userAgent});}catch{toast('Channels loaded. EPG could not be updated; the previous guide was kept.');}}return {channels:parsed.channels,programs:epg.programs,epgNames:epg.names,epgURL,lastUpdated:Date.now()};}
