  function renderInfo(){syncPlaybackStatus();if(state.view==='mylist')return;const c=currentChannel();if(!c||(state.view==='guide'&&c.type!=='tv')){for(const id of ['program-title','program-meta','program-time','program-description'])$('#'+id).textContent='';return;}const p=state.selected||programAt(c),now=Date.now();$('#program-title').textContent=c.type==='movie'?c.name+(c.year?' ('+c.year+')':''):p.empty?c.name:p.title;$('#program-meta').textContent=c.type==='movie'?'':p.category||c.group;$('#program-time').innerHTML=p.empty?'<span class="epg-unavailable">No programme information</span>':`<span>${fmt(p.start)} – ${fmt(p.end)}</span><div class="progress-track"><i style="width:${Math.min(100,Math.max(0,(now-p.start)/(p.end-p.start)*100))}%"></i></div><span>${p.start>now?mins(p.start-now)+' min':mins(p.end-now)+' min'}</span>`;$('#program-description').textContent=c.type==='movie'?c.description||'':p.empty?'':p.description||'';let star=$('.info-star');if(!star){star=document.createElement('button');star.className='info-star';star.dataset.action='favorite';star.setAttribute('aria-label','Add to favorites');$('.program-info').append(star);}star.setAttribute('aria-label',state.favorites.includes(c.id)?'Remove from favorites':'Add to favorites');star.setAttribute('aria-pressed',String(state.favorites.includes(c.id)));star.innerHTML=icon('star');star.classList.toggle('active',state.favorites.includes(c.id));$('#foot-status').textContent=state.source;if(c.type==='movie')movieBackdrop(c);}
  let lastGuideChannel='',guideSource=null,guideGroup='',guideScroll=0,guideActive=null;
