import {hash} from './core.mjs';
export function xtreamApi(server,username,password,action,id=null){const url=new URL(server);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error('Invalid Xtream server.');url.pathname=url.pathname.replace(/\/$/,'')+'/player_api.php';url.search='';url.searchParams.set('username',username);url.searchParams.set('password',password);url.searchParams.set('action',action);if(id!==null)url.searchParams.set(action==='get_series_info'?'series_id':'vod_id',String(id));return url.href;}
export function xtreamMovie(item,credentials){const id=Number(item.stream_id);if(!Number.isSafeInteger(id)||id<=0)return null;const ext=String(item.container_extension||'mp4').replace(/[^a-zA-Z0-9]/g,'')||'mp4';const root=credentials.server.replace(/\/$/,'');return {id:'vod-'+hash(root+'|'+credentials.username+'|'+id),name:String(item.name||'Movie'),group:String(item.category_name||'Movies'),type:'movie',url:root+'/movie/'+encodeURIComponent(credentials.username)+'/'+encodeURIComponent(credentials.password)+'/'+id+'.'+ext,poster:String(item.stream_icon||item.cover||''),added:Number(item.added)||0,year:item.year||'',description:String(item.plot||''),xtream:{server:root,username:credentials.username,password:credentials.password,vodId:id}};}
export function xtreamSeries(item,credentials){const id=Number(item.series_id);if(!Number.isSafeInteger(id)||id<=0)return null;const root=credentials.server.replace(/\/$/,'');return {id:'series-show-'+hash(root+'|'+credentials.username+'|'+id),name:String(item.name||'Series'),group:String(item.category_name||'Series'),type:'series',url:'',poster:String(item.cover||item.stream_icon||''),xtream:{...credentials,server:root,seriesId:id}};}
export function xtreamEpisodes(raw,show){const seasons=raw?.episodes||{};const all=[];for(const [season,parts] of Object.entries(seasons)){if(!Array.isArray(parts))continue;for(const e of parts){if(!e||!e.id)continue;const ext=String(e.container_extension||'mp4').replace(/[^a-zA-Z0-9]/g,'')||'mp4';const cr=show.xtream;all.push({id:'ep-'+hash(cr.server+'|'+cr.username+'|'+e.id),name:String(e.title||show.name+' S'+season+' E'+(e.episode_num||1)),group:show.group,seriesShowName:show.name,type:'series',url:cr.server+'/series/'+encodeURIComponent(cr.username)+'/'+encodeURIComponent(cr.password)+'/'+encodeURIComponent(e.id)+'.'+ext,poster:String(e.info?.movie_image||show.poster||''),season:Number(season)||1,episode:Number(e.episode_num)||1});}}return all.sort((a,b)=>a.season-b.season||a.episode-b.episode);}
